class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        if monthly_limit_mib < 0:
            raise ValueError("Monthly limit cannot be negative.")
        # 1 MiB = 1024 * 1024 bytes = 1,048,576 bytes
        self._monthly_limit_bytes = int(monthly_limit_mib * 1024 * 1024)

        # Track files uploaded per month: month -> {name: size_bytes}
        self._monthly_files: dict[str, dict[str, int]] = {}
        # Track total quota consumed per month: month -> int
        self._monthly_used: dict[str, int] = {}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        """month is a string like '2026-01'."""
        if size_bytes <= 0:
            raise ValueError("File size must be strictly positive.")

        files_in_month = self._monthly_files.setdefault(month, {})
        current_used = self._monthly_used.setdefault(month, 0)

        # Uploading again a file with the same name in the same month
        # does not count towards the limit a second time.
        if name in files_in_month:
            return

        if current_used + size_bytes > self._monthly_limit_bytes:
            raise ValueError("Upload exceeds the monthly quota limit.")

        files_in_month[name] = size_bytes
        self._monthly_used[month] = current_used + size_bytes

    def delete(self, name: str, month: str) -> None:
        """
        Delete a file. Deleting a file does not give back quota in the current month.
        """
        files_in_month = self._monthly_files.get(month, {})
        files_in_month.pop(name, None)

    def used_bytes(self, month: str) -> int:
        """How many bytes count towards the quota in the given month."""
        return self._monthly_used.get(month, 0)
